contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Accept incoming Ether when C may transfer back to this contract
    receive() external payable {}

    // Single public test function driving C via its fallback; amount and simulated block conditions
    function run(uint sendAmount) public payable {
        // we only model the meaningful transfer amount
        require(address(this).balance >= sendAmount);

        // Read before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Perform the call to fallback, capturing whether it reverted
        bool reverted;
        // Note: calling fallback by calling with empty data
        try c.call{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values (only through public surface)
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule:
        // If the call reverted, nothing is guaranteed about balances or pastBlockTime (other than EVM semantics),
        // but if it did NOT revert and the call provided exactly 10 ether, then:
        //  - pastBlockTime must have been updated to block.timestamp + 1
        //  - if block.number % 15 == 0 then the contract forwarded its entire balance (so afterBal == 0)
        //  - otherwise the contract kept the funds (so afterBal == beforeBal + 10 ether)

        assert(
            // If reverted, accept (must be reachable as some executions revert)
            reverted
            || (
                sendAmount == 10 ether
                && afterPast == (uint(block.timestamp) + 1)
                && (
                    (block.number % 15 == 0 && afterBal == 0)
                    || (block.number % 15 != 0 && afterBal == beforeBal + 10 ether)
                )
            )
        );
    }

    // low-level call wrapper to invoke fallback of C
    fallback() external payable { /* not used */ }
}

