contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept parameters: amount to send (must be 10 ether to avoid early revert) and
    // a dummy blockNumberMod15 flag to model whether block.number % 15 == 0.
    // Note: we cannot read block.number here to force a behaviour, but the property
    // will consider the observed effects (balance and pastBlockTime) after the call.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // Observe before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Make the call to fallback by sending Ether with empty calldata
        bool reverted;
        // The contract's fallback requires msg.value == 10 ether, so calls with other amounts must revert
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule asserted:
        // - If the call reverted, nothing is required about c's state here (we allow revert for any non-10 ether amount).
        // - If the call did not revert:
        //     * pastBlockTime strictly increases (pastBlockTime > beforePast)
        //     * and either the contract balance is 0 (meaning it transferred out full balance to sender) or it increased by exactly amount.
        // This captures that a successful call advances time and either causes full withdraw on block%15==0 or otherwise simply deposits the sent ether.
        assert(
            reverted || (
                afterPast > beforePast
                && (
                    (afterBal == 0) || (afterBal == beforeBal + amount)
                )
            )
        );
    }

    // allow receiving Ether in case fallback of C sends funds back to this test contract
    receive() external payable {}
}

