contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept parameters: amount to send (must be 10 ether to avoid immediate require revert)
    // and a dummy uint to allow variation (not used except in assert to keep it non-constant).
    function run(uint dummy, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to forward");
        // Precondition: only consider sending exactly 10 ether to hit the main branch; otherwise the call must revert.
        bool reverted;
        uint beforePast = c.pastBlockTime();
        uint beforeBalC = address(c).balance;
        uint beforeBalThis = address(this).balance;

        // perform the call to fallback by sending value; must be a top-level statement
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBalC = address(c).balance;
        uint afterBalThis = address(this).balance;

        // General property asserted:
        // - If the call did not revert and amount == 10 ether then pastBlockTime increased and equals block.timestamp+1
        //   (we can't read block.timestamp here, but we can assert it strictly increased when non-reverted and amount==10e18).
        // - If the call did not revert and block.number % 15 == 0 then contract balance becomes 0 and this contract's balance did not decrease.
        // - If the call reverted then no state changes occurred to pastBlockTime or balances.
        // We express these observations using only accessible getters and parameters.

        assert(
            (
                // Case: call reverted -> nothing changed
                reverted && afterPast == beforePast && afterBalC == beforeBalC && afterBalThis == beforeBalThis
            ) || (
                // Case: call succeeded and we sent exactly 10 ether
                !reverted && amount == 10 ether && afterPast > beforePast &&
                (
                    // If block.number % 15 == 0 then contract drained to zero and this contract's balance did not decrease
                    (block.number % 15 == 0 && afterBalC == 0 && afterBalThis >= beforeBalThis) ||
                    // Otherwise contract balance is >= previous balance - (it may have increased by the sent amount)
                    (block.number % 15 != 0 && afterBalC >= beforeBalC)
                )
            )
        );
    }

    // Allow receiving Ether from C when it withdraws
    receive() external payable {}
 }

